// WebAssembly demo for the 🩹 Stitch Me Up engine.
//
// `pkg/stitch_wasm.js` is generated by wasm-pack; build it before serving this page:
//   cd crates/stitch-wasm && wasm-pack build --target web --out-dir ../../examples/web/pkg
import init, { Composer } from "./pkg/stitch_wasm.js";

const $ = (id) => document.getElementById(id);

const state = {
  composer: null,
  objectUrl: null,
  initFailed: false,
};

const composeButton = $("compose");

function showError(message) {
  const box = $("error");
  box.textContent = message;
  box.hidden = false;
}

function clearError() {
  $("error").textContent = "";
  $("error").hidden = true;
}

function setLayout() {
  const layout = $("layout").value;
  // The core rejects dividers for every layout except before-after, so the divider
  // controls are only meaningful there.
  const dividerEnabled = layout === "before-after";
  $("divider-width").disabled = !dividerEnabled;
  $("divider-color").disabled = !dividerEnabled;
  $("columns").disabled = layout !== "grid";
}

$("layout").addEventListener("change", setLayout);
setLayout();

init()
  .then(() => {
    state.composer = new Composer();
    composeButton.disabled = false;
    $("status").textContent = "Ready.";
  })
  .catch((error) => {
    state.initFailed = true;
    $("status").textContent = "WebAssembly module failed to load.";
    showError(`${error.message} — build the module first with ` +
      "cd crates/stitch-wasm && wasm-pack build --target web --out-dir ../../examples/web/pkg, " +
      "then serve this directory (see examples/web/README.md).");
  });

function selectedFiles() {
  return Array.from($("files").files);
}

function readBytes(file) {
  return file.arrayBuffer().then((buffer) => new Uint8Array(buffer));
}

function composeAll() {
  clearError();

  if (state.initFailed) {
    showError("The WebAssembly module is not loaded; build it with wasm-pack first.");
    return Promise.resolve();
  }

  const files = selectedFiles();
  if (files.length < 2) {
    showError("Pick at least two images.");
    return Promise.resolve();
  }

  return Promise.all(files.map(readBytes))
    .then((buffers) => {
      const composer = new Composer();
      const layout = $("layout").value;

      composer.set_layout(layout, Math.max(1, Number($("columns").value)));
      composer.set_spacing(Number($("spacing-x").value), Number($("spacing-y").value));
      composer.set_padding(Number($("pad-top").value), Number($("pad-right").value),
        Number($("pad-bottom").value), Number($("pad-left").value));
      composer.set_background($("background").value);
      composer.set_alignment($("alignment").value);
      composer.set_resize_mode($("resize-mode").value);
      composer.set_frame(Number($("frame-width").value), $("frame-color").value);
      composer.set_corner_radius(Number($("corner-radius").value));

      // set_divider would make the core reject the composition for other layouts.
      if (layout === "before-after") {
        composer.set_divider(Number($("divider-width").value), $("divider-color").value);
      }

      const png = composer.compose(buffers);

      if (state.objectUrl !== null) {
        URL.revokeObjectURL(state.objectUrl);
      }
      state.objectUrl = URL.createObjectURL(new Blob([png], { type: "image/png" }));

      const preview = $("preview");
      preview.src = state.objectUrl;
      preview.hidden = false;

      const download = $("download");
      download.href = state.objectUrl;
      download.hidden = false;
    })
    .catch((error) => {
      showError(error.message);
    });
}

composeButton.addEventListener("click", () => {
  try {
    composeAll().catch((error) => showError(error.message));
  } catch (error) {
    showError(error.message);
  }
});
